function Header() {
  return (
    <header className="h-20 flex items-center px-6 bg-white border-b">
      {/* Use flex container for the entire header */}
      <div className="flex justify-between w-full">

        {/* Left */}
        <h1 className="text-xl font-semibold">Left</h1>

        {/* Center */}
        <h1 className="text-xl font-semibold">Center</h1>

        {/* Right */}
        <h1 className="text-xl font-semibold">Right</h1>

      </div>
    </header>
  );
}

export default Header;
